static void test_reduce(void) {
    TEST_SUITE("p256_reduce — T mod p, canonical, against a Python oracle");

    for (int i = 0; i < NVECS; i++) {
        uint64_t out[4];
        p256_reduce(out, VECS[i].T);
        ASSERT_EQ("T mod p", 0, memcmp(out, VECS[i].r, sizeof(out)));
    }
}

int main(void) {
    test_reduce();
    test_summary();
    return 0;
}
